export const CLAUDE_DESIGN_HTML = "<style>\n  html { scroll-behavior: smooth; }\n  body { margin: 0; background: var(--color-canvas); }\n  a { color: inherit; text-decoration: none; }\n  a:hover { color: var(--color-white); }\n  ::selection { background: var(--color-ink); color: var(--color-canvas); }\n  summary { list-style: none; cursor: pointer; }\n  summary::-webkit-details-marker { display: none; }\n  details[open] .faq-plus { transform: rotate(45deg); }\n  @keyframes riseIn { from { opacity: 0; transform: translateY(26px); } to { opacity: 1; transform: translateY(0); } }\n  @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }\n  @keyframes spin { to { transform: rotate(360deg); } }\n  @keyframes feedPaper { from { transform: translateY(-101%); } to { transform: translateY(-1%); } }\n</style><div style=\"background:var(--color-canvas);color:var(--color-ink);font-family:var(--font-sans),'Helvetica Neue',Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased\">\n\n  <div data-claude-ref=\"setProgress\" style=\"position:fixed;left:0;top:0;height:1px;width:0;background:var(--color-ink);z-index:60\"></div>\n\n  <header data-claude-ref=\"setHeader\" style=\"position:sticky;top:0;z-index:50;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:20px 34px;background:var(--color-header);backdrop-filter:blur(14px);border-bottom:1px solid transparent;transition:border-color .25s\">\n    <a href=\"#top\" style=\"display:flex;align-items:baseline;gap:10px;flex:none;white-space:nowrap\">\n      <span style=\"font-size:18px;font-weight:500;letter-spacing:-0.02em\">Resvary.</span>\n      <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-muted)\">0.4 alpha</span>\n    </a>\n    <nav aria-label=\"Primary\" style=\"display:flex;align-items:center;flex-wrap:wrap;column-gap:clamp(10px,1.7vw,26px);row-gap:8px;min-width:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:clamp(10.5px,0.85vw,12px);letter-spacing:clamp(0.06em,0.45vw,0.11em);text-transform:uppercase;white-space:nowrap;color:var(--color-ink-body)\">\n      <a href=\"#product\" style=\"transition:color .2s\">Product</a>\n      <a href=\"#how\" style=\"transition:color .2s\">How it works</a>\n      <a href=\"#demo\" style=\"transition:color .2s\">Demo</a>\n      <a href=\"#use-cases\" style=\"transition:color .2s\">Use cases</a>\n      <a href=\"#pricing\" style=\"transition:color .2s\">Access</a>\n      <a href=\"https://github.com/horn111/resvary#readme\" style=\"transition:color .2s\">Docs</a>\n      <a href=\"https://github.com/horn111/resvary\" style=\"transition:color .2s\">GitHub</a>\n    </nav>\n    <details data-mobile-nav=\"true\">\n      <summary>Menu</summary>\n      <nav aria-label=\"Mobile\">\n        <a href=\"#product\">Product</a>\n        <a href=\"#how\">How it works</a>\n        <a href=\"#demo\">Demo</a>\n        <a href=\"#use-cases\">Use cases</a>\n        <a href=\"#pricing\">Access</a>\n        <a href=\"https://github.com/horn111/resvary#readme\">Docs</a>\n        <a href=\"https://github.com/horn111/resvary\">GitHub</a>\n      </nav>\n    </details>\n    <a href=\"#interactive-demo\" style=\"position:relative;flex:none;display:inline-flex;align-items:center;padding:13px clamp(14px,1.4vw,20px);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:clamp(10.5px,0.85vw,12px);letter-spacing:clamp(0.07em,0.45vw,0.11em);text-transform:uppercase;white-space:nowrap;color:var(--color-ink-strong);transition:color .2s\" data-hover-style=\"color:var(--color-white)\">\n      <span style=\"position:absolute;left:0;top:0;width:11px;height:11px;border-left:1px solid var(--color-ink-muted);border-top:1px solid var(--color-ink-muted)\"></span>\n      <span style=\"position:absolute;right:0;top:0;width:11px;height:11px;border-right:1px solid var(--color-ink-muted);border-top:1px solid var(--color-ink-muted)\"></span>\n      <span style=\"position:absolute;left:0;bottom:0;width:11px;height:11px;border-left:1px solid var(--color-ink-muted);border-bottom:1px solid var(--color-ink-muted)\"></span>\n      <span style=\"position:absolute;right:0;bottom:0;width:11px;height:11px;border-right:1px solid var(--color-ink-muted);border-bottom:1px solid var(--color-ink-muted)\"></span>\n      Run the live demo\n    </a>\n  </header><main id=\"main-content\" tabindex=\"-1\">\n\n  <section id=\"top\" data-screen-label=\"Hero\" style=\"position:relative;min-height:calc(100vh - 62px);display:flex;flex-direction:column;overflow:hidden\">\n    <div style=\"position:absolute;inset:0;background:radial-gradient(70% 55% at 50% 46%, rgba(255,255,255,0.05), transparent 70%);pointer-events:none\"></div>\n\n    <div style=\"position:relative;z-index:2;flex:1;display:flex;align-items:center;padding:40px 34px 0\">\n      <div style=\"position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(50vh,540px);height:min(50vh,540px);animation:fadeIn 1.6s ease both\">\n        <canvas data-claude-ref=\"setCanvas\" style=\"display:block;width:100%;height:100%\"></canvas>\n      </div>\n      <h1 style=\"position:relative;z-index:2;margin:0;width:100%;display:flex;align-items:center;justify-content:space-between;gap:min(5vw,90px);font-size:clamp(34px,4.9vw,74px);line-height:0.98;letter-spacing:-0.038em;font-weight:500;pointer-events:none\">\n        <span style=\"display:flex;flex-direction:column\">\n          <span style=\"animation:riseIn 0.9s cubic-bezier(.2,.7,.2,1) 0.05s both\">Prepaid credits</span>\n          <span style=\"animation:riseIn 0.9s cubic-bezier(.2,.7,.2,1) 0.14s both\">and usage billing</span>\n        </span>\n        <span style=\"display:flex;flex-direction:column;text-align:right\">\n          <span style=\"animation:riseIn 0.9s cubic-bezier(.2,.7,.2,1) 0.26s both\">for AI</span>\n          <span style=\"animation:riseIn 0.9s cubic-bezier(.2,.7,.2,1) 0.35s both\">products</span>\n        </span>\n      </h1>\n    </div>\n\n    <div style=\"position:relative;z-index:3;display:flex;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;gap:40px;padding:0 34px 44px;animation:fadeIn 1.1s ease 0.45s both\">\n      <div style=\"display:flex;flex-direction:column;gap:22px;max-width:54ch\">\n        <div style=\"display:inline-flex;align-items:center;gap:9px;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-subtle)\">\n          <span style=\"width:5px;height:5px;background:var(--color-ink)\"></span>\n          Open source · 0.4 alpha\n        </div>\n        <p style=\"margin:0;font-size:16.5px;line-height:1.55;color:var(--color-ink-body);text-wrap:pretty\">\n          Reserve a maximum cost before an AI job runs. Charge the actual usage when it finishes. Release the rest and give users an auditable receipt.\n        </p>\n        <div style=\"display:flex;flex-wrap:wrap;gap:12px\">\n          <a href=\"#interactive-demo\" style=\"display:inline-flex;align-items:center;gap:10px;padding:14px 22px;background:var(--color-ink);color:var(--color-canvas);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;transition:opacity .2s\" data-hover-style=\"opacity:0.82;color:var(--color-canvas)\">Run the live demo <span style=\"opacity:0.5\">→</span></a>\n          <a href=\"https://github.com/horn111/resvary\" style=\"display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:1px solid var(--color-line-strong);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-strong);transition:border-color .2s, color .2s\" data-hover-style=\"border-color:var(--color-ink-subtle);color:var(--color-white)\">View source on GitHub</a>\n        </div>\n      </div>\n      <div style=\"flex:none;display:flex;flex-direction:column;align-items:flex-end;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11.5px;line-height:2;letter-spacing:0.1em;text-transform:uppercase;white-space:nowrap;color:var(--color-ink-muted)\">\n        <span>Apache-2.0</span>\n        <span>TypeScript · Embedded SDK</span>\n        <span>SQLite alpha backend</span>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"product\" data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:min(8vw,110px);align-items:start\">\n      <div>\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">01 / Problem</div>\n        <h2 style=\"margin:0;font-size:clamp(30px,3.6vw,54px);line-height:1.02;letter-spacing:-0.032em;font-weight:500;max-width:22ch;text-wrap:balance\">AI usage has a timing problem</h2>\n      </div>\n      <div style=\"display:flex;flex-direction:column;gap:26px\">\n        <p style=\"margin:0;font-size:17px;line-height:1.6;color:var(--color-ink-body);text-wrap:pretty\">You must decide whether a customer can start an AI request before the final cost exists. Tokens, seconds, images, and tool calls arrive after the provider finishes.</p>\n        <p style=\"margin:0;font-size:17px;line-height:1.6;color:var(--color-ink-strong);text-wrap:pretty\">Resvary checks available credits and creates a reservation before provider work begins. It commits the final charge after execution and releases the unused amount.</p>\n        <ul style=\"list-style:none;margin:14px 0 0;padding:0;display:flex;flex-direction:column\">\n          <li style=\"display:flex;gap:16px;padding:15px 0;border-top:1px solid var(--color-line);font-size:15.5px;line-height:1.5;color:var(--color-ink-body)\"><span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;color:var(--color-ink-muted);padding-top:3px\">01</span>Concurrent jobs can spend the same apparent balance.</li>\n          <li style=\"display:flex;gap:16px;padding:15px 0;border-top:1px solid var(--color-line);font-size:15.5px;line-height:1.5;color:var(--color-ink-body)\"><span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;color:var(--color-ink-muted);padding-top:3px\">02</span>A retried request can create a duplicate charge.</li>\n          <li style=\"display:flex;gap:16px;padding:15px 0;border-top:1px solid var(--color-line);font-size:15.5px;line-height:1.5;color:var(--color-ink-body)\"><span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;color:var(--color-ink-muted);padding-top:3px\">03</span>Failed jobs can leave credits locked without an explicit release.</li>\n          <li style=\"display:flex;gap:16px;padding:15px 0;border-top:1px solid var(--color-line);font-size:15.5px;line-height:1.5;color:var(--color-ink-body)\"><span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;color:var(--color-ink-muted);padding-top:3px\">04</span>Mutable prices make old charges hard to explain.</li>\n          <li style=\"display:flex;gap:16px;padding:15px 0;border-top:1px solid var(--color-line);border-bottom:1px solid var(--color-line);font-size:15.5px;line-height:1.5;color:var(--color-ink-body)\"><span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;color:var(--color-ink-muted);padding-top:3px\">05</span>A balance snapshot cannot show why the number changed.</li>\n        </ul>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"how\" data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto\">\n      <div style=\"display:flex;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;gap:32px;margin-bottom:56px\">\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">02 / Credit lifecycle</div>\n          <h2 style=\"margin:0;font-size:clamp(30px,3.6vw,54px);line-height:1.02;letter-spacing:-0.032em;font-weight:500;max-width:26ch;text-wrap:balance\">One lifecycle from authorization to receipt</h2>\n        </div>\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.1em;color:var(--color-ink-subtle);border:1px dashed var(--color-line-strong);padding:12px 16px\">Fund → Reserve → Execute → Commit → Release → Receipt</div>\n      </div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1px;background:var(--color-line)\">\n        <div style=\"background:var(--color-canvas);padding:30px 26px 34px;display:flex;flex-direction:column;gap:14px;transition:background .25s\" data-hover-style=\"background:var(--color-surface-raised)\">\n          <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;color:var(--color-ink-muted)\">STEP 01</span>\n          <h3 style=\"margin:0;font-size:20px;font-weight:500;letter-spacing:-0.02em\">Fund the account</h3>\n          <p style=\"margin:0;font-size:15px;line-height:1.55;color:var(--color-ink-muted)\">Grant credits manually, from a direct Arc USDC transfer, or from a Circle Gateway Nanopayment. All three fund the same ledger.</p>\n        </div>\n        <div style=\"background:var(--color-canvas);padding:30px 26px 34px;display:flex;flex-direction:column;gap:14px;transition:background .25s\" data-hover-style=\"background:var(--color-surface-raised)\">\n          <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;color:var(--color-ink-muted)\">STEP 02</span>\n          <h3 style=\"margin:0;font-size:20px;font-weight:500;letter-spacing:-0.02em\">Reserve the maximum cost</h3>\n          <p style=\"margin:0;font-size:15px;line-height:1.55;color:var(--color-ink-muted)\">Rate the estimated usage against an immutable price version and hold that amount before expensive work begins.</p>\n        </div>\n        <div style=\"background:var(--color-canvas);padding:30px 26px 34px;display:flex;flex-direction:column;gap:14px;transition:background .25s\" data-hover-style=\"background:var(--color-surface-raised)\">\n          <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;color:var(--color-ink-muted)\">STEP 03</span>\n          <h3 style=\"margin:0;font-size:20px;font-weight:500;letter-spacing:-0.02em\">Run the AI operation</h3>\n          <p style=\"margin:0;font-size:15px;line-height:1.55;color:var(--color-ink-muted)\">Call a model, agent, generation pipeline, tool, or batch worker with your existing provider stack.</p>\n        </div>\n        <div style=\"background:var(--color-canvas);padding:30px 26px 34px;display:flex;flex-direction:column;gap:14px;transition:background .25s\" data-hover-style=\"background:var(--color-surface-raised)\">\n          <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;color:var(--color-ink-muted)\">STEP 04</span>\n          <h3 style=\"margin:0;font-size:20px;font-weight:500;letter-spacing:-0.02em\">Commit actual usage</h3>\n          <p style=\"margin:0;font-size:15px;line-height:1.55;color:var(--color-ink-muted)\">Rate the provider's final usage, charge it once, and release the unused part of the reservation in the same transaction.</p>\n        </div>\n        <div style=\"background:var(--color-canvas);padding:30px 26px 34px;display:flex;flex-direction:column;gap:14px;transition:background .25s\" data-hover-style=\"background:var(--color-surface-raised)\">\n          <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;color:var(--color-ink-muted)\">STEP 05</span>\n          <h3 style=\"margin:0;font-size:20px;font-weight:500;letter-spacing:-0.02em\">Record the result</h3>\n          <p style=\"margin:0;font-size:15px;line-height:1.55;color:var(--color-ink-muted)\">Store an immutable ledger entry, usage receipt, idempotency result, and outbox event for reconciliation.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto\">\n      <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">03 / Why Resvary</div>\n      <h2 style=\"margin:0 0 56px;font-size:clamp(30px,3.6vw,54px);line-height:1.02;letter-spacing:-0.032em;font-weight:500;max-width:24ch;text-wrap:balance\">The credit boundary around each AI call</h2>\n      <div data-benefit-grid=\"true\" style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:44px 60px\">\n        <div style=\"display:flex;flex-direction:column;gap:14px;padding-top:24px;border-top:1px solid var(--color-line)\">\n          <h3 style=\"margin:0;font-size:22px;font-weight:500;letter-spacing:-0.022em;max-width:20ch\">Authorize spend before execution</h3>\n          <p style=\"margin:0;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">Resvary checks available credits and creates an atomic reservation before your application starts provider work. Overlapping requests cannot reserve the same credits twice when the store supplies the required transaction isolation.</p>\n        </div>\n        <div style=\"display:flex;flex-direction:column;gap:14px;padding-top:24px;border-top:1px solid var(--color-line)\">\n          <h3 style=\"margin:0;font-size:22px;font-weight:500;letter-spacing:-0.022em;max-width:20ch\">Charge once across retries</h3>\n          <p style=\"margin:0;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">Every mutating command requires an idempotency key. Replaying the same key and payload returns the original result. Reusing the key with different input raises a conflict.</p>\n        </div>\n        <div style=\"display:flex;flex-direction:column;gap:14px;padding-top:24px;border-top:1px solid var(--color-line)\">\n          <h3 style=\"margin:0;font-size:22px;font-weight:500;letter-spacing:-0.022em;max-width:20ch\">Explain each balance change</h3>\n          <p style=\"margin:0;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">Immutable ledger entries and per-charge usage receipts record the price version, line items, amount charged, amount released, and balance after the operation.</p>\n        </div>\n        <div style=\"display:flex;flex-direction:column;gap:14px;padding-top:24px;border-top:1px solid var(--color-line)\">\n          <h3 style=\"margin:0;font-size:22px;font-weight:500;letter-spacing:-0.022em;max-width:20ch\">Keep payment rails separate from usage</h3>\n          <p style=\"margin:0;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">The credit lifecycle does not depend on an AI provider. Manual grants, direct Arc USDC transfers, and Circle Gateway Nanopayments all fund the same ledger without changing usage accounting.</p>\n        </div>\n      </div>\n\n      <div id=\"receipt-printer\" style=\"margin-top:76px;padding-top:46px;border-top:1px solid var(--color-line);display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:min(7vw,80px);align-items:start\">\n        <div style=\"display:flex;flex-direction:column;gap:20px\">\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted)\">Usage receipt</div>\n          <h3 style=\"margin:0;font-size:clamp(24px,2.4vw,34px);line-height:1.08;font-weight:500;letter-spacing:-0.026em;max-width:20ch;text-wrap:balance\">Each commit records its own explanation</h3>\n          <p style=\"margin:0;font-size:15.5px;line-height:1.6;color:var(--color-ink-body);max-width:46ch\">The usage receipt records the price version, line items, final charge, released credits, and resulting balance. Your team can trace each balance change without reconstructing it from logs.</p>\n          <button type=\"button\" data-claude-print=\"true\" style=\"align-self:flex-start;display:inline-flex;align-items:center;gap:10px;padding:14px 22px;background:transparent;border:1px solid var(--color-line-strong);color:var(--color-ink-strong);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;cursor:pointer;transition:border-color .2s, color .2s\" data-hover-style=\"border-color:var(--color-ink-subtle);color:var(--color-white)\">Print sample receipt <span style=\"opacity:0.5\">↻</span></button>\n        </div>\n\n        <div style=\"display:flex;flex-direction:column;align-items:center;width:100%\">\n          <div style=\"position:relative;z-index:3;width:100%;max-width:430px;display:flex;flex-direction:column;gap:14px;padding:16px 16px 13px;background:linear-gradient(180deg,#191919,#0d0d0d);border:1px solid var(--color-line);box-shadow:0 20px 44px -26px rgba(0,0,0,0.95)\">\n            <div style=\"display:flex;align-items:center;justify-content:space-between;gap:16px;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted)\">\n              <span style=\"display:flex;align-items:center;gap:9px\"><span style=\"width:6px;height:6px;background:var(--color-ink)\"></span>Resvary ledger</span>\n              <span data-claude-ref=\"setPrintStatus\" style=\"white-space:nowrap\">0.4 alpha</span>\n            </div>\n            <div style=\"height:12px;background:#050505;border:1px solid var(--color-line);box-shadow:inset 0 3px 7px rgba(0,0,0,0.95)\"></div>\n            <div style=\"display:flex;align-items:center;gap:11px;padding-top:3px;font-size:13.5px;color:rgba(242,242,240,0.82)\">\n              <span data-claude-ref=\"setSpinner\" style=\"flex:none;width:14px;height:14px;border-radius:50%;border:1.5px solid var(--color-line-strong);border-top-color:var(--color-ink);animation:spin 0.8s linear infinite\"></span>\n              <span data-claude-ref=\"setDoneMark\" style=\"flex:none;display:none;width:14px;height:14px;border-radius:50%;background:var(--color-ink);color:var(--color-canvas);font-size:9px;line-height:14px;text-align:center\">✓</span>\n              <span data-claude-ref=\"setPrintLine\" role=\"status\" aria-live=\"polite\" style=\"white-space:nowrap\">Reserving credits</span>\n            </div>\n          </div>\n\n          <div style=\"width:min(372px,94%);overflow:hidden\">\n            <div data-claude-ref=\"setPaper\" style=\"transform:translateY(-101%);background:var(--color-ink);color:var(--color-canvas);padding:22px 22px 30px;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11.5px;line-height:1.75;letter-spacing:0.02em;white-space:nowrap;box-shadow:0 24px 46px -30px rgba(0,0,0,0.95);-webkit-mask:radial-gradient(7px at 50% 0,#0000 97%,#000) 50% 100%/15px 8px repeat-x,linear-gradient(#000,#000) 0 0/100% calc(100% - 8px) no-repeat;mask:radial-gradient(7px at 50% 0,#0000 97%,#000) 50% 100%/15px 8px repeat-x,linear-gradient(#000,#000) 0 0/100% calc(100% - 8px) no-repeat\">\n              <div style=\"display:flex;align-items:baseline;justify-content:space-between;gap:12px;font-size:10.5px;letter-spacing:0.16em;text-transform:uppercase;color:rgba(10,10,10,0.62)\">\n                <span>Resvary · usage receipt</span>\n                <span>0.4 alpha</span>\n              </div>\n              <div style=\"margin:14px 0;border-top:1px dashed rgba(10,10,10,0.32)\"></div>\n              <div style=\"display:flex;flex-direction:column;gap:4px;color:rgba(10,10,10,0.72)\">\n                <div style=\"display:flex;justify-content:space-between;gap:16px\"><span>RECEIPT</span><span style=\"color:var(--color-canvas)\">rcp_8f42c1</span></div>\n                <div style=\"display:flex;justify-content:space-between;gap:16px\"><span>ACCOUNT</span><span style=\"color:var(--color-canvas)\">acct_studio_04</span></div>\n                <div style=\"display:flex;justify-content:space-between;gap:16px\"><span>METER</span><span style=\"color:var(--color-canvas)\">tokens.chat</span></div>\n                <div style=\"display:flex;justify-content:space-between;gap:16px\"><span>PRICE VERSION</span><span style=\"color:var(--color-canvas)\">pv_7</span></div>\n              </div>\n              <div style=\"margin:14px 0;border-top:1px dashed rgba(10,10,10,0.32)\"></div>\n              <div style=\"display:flex;flex-direction:column;gap:4px;color:rgba(10,10,10,0.72)\">\n                <div style=\"display:flex;justify-content:space-between;gap:16px\"><span>INPUT · 18,400 tok</span><span style=\"color:var(--color-canvas)\">0.055200</span></div>\n                <div style=\"display:flex;justify-content:space-between;gap:16px\"><span>OUTPUT · 2,440 tok</span><span style=\"color:var(--color-canvas)\">0.073200</span></div>\n              </div>\n              <div style=\"margin:14px 0;border-top:1px dashed rgba(10,10,10,0.32)\"></div>\n              <div style=\"display:flex;flex-direction:column;gap:5px\">\n                <div style=\"display:flex;justify-content:space-between;gap:16px;color:rgba(10,10,10,0.72)\"><span>RESERVED</span><span>$0.400000</span></div>\n                <div style=\"display:flex;justify-content:space-between;gap:16px;font-size:14px;font-weight:500;color:var(--color-canvas)\"><span>CHARGED</span><span>$0.128400</span></div>\n                <div style=\"display:flex;justify-content:space-between;gap:16px;color:rgba(10,10,10,0.72)\"><span>RELEASED</span><span>$0.271600</span></div>\n                <div style=\"display:flex;justify-content:space-between;gap:16px;color:rgba(10,10,10,0.72)\"><span>BALANCE AFTER</span><span>$4.871600</span></div>\n              </div>\n              <div style=\"margin:14px 0;border-top:1px dashed rgba(10,10,10,0.32)\"></div>\n              <div style=\"display:flex;flex-direction:column;gap:3px;font-size:10.5px;color:rgba(10,10,10,0.6)\">\n                <span>IDEMPOTENCY  req_5c9d0e7a3b</span>\n                <span>COMMITTED    2026-08-14 09:41:02Z</span>\n                <span>LEDGER       le_1183 · le_1184</span>\n              </div>\n              <div style=\"display:flex;align-items:flex-end;gap:2px;height:34px;margin-top:18px\">\n                <div style=\"width:2px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:4px;height:82%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:66%;background:var(--color-canvas)\"></div>\n                <div style=\"width:5px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:78%;background:var(--color-canvas)\"></div>\n                <div style=\"width:3px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:60%;background:var(--color-canvas)\"></div>\n                <div style=\"width:4px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:84%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:5px;height:70%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:3px;height:88%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:4px;height:64%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:80%;background:var(--color-canvas)\"></div>\n                <div style=\"width:5px;height:100%;background:var(--color-canvas)\"></div>\n                <div style=\"width:2px;height:72%;background:var(--color-canvas)\"></div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:grid;grid-template-columns:minmax(0,0.8fr) minmax(0,1.2fr);gap:min(8vw,110px);align-items:start\">\n      <div>\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">04 / Included in alpha</div>\n        <h2 style=\"margin:0;font-size:clamp(30px,3.6vw,54px);line-height:1.02;letter-spacing:-0.032em;font-weight:500;max-width:18ch;text-wrap:balance\">Credit primitives that survive retries</h2>\n      </div>\n      <ul style=\"list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:0 40px;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;line-height:1.5;color:var(--color-ink-body)\">\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Closed-loop USD product credit accounts</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Six-decimal integer credit arithmetic</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Multi-dimensional usage meters</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Immutable price versions</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Estimated-usage reservations</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Actual-usage commit and release</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Expiring open reservations</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Persistent idempotency records</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Append-only ledger entries</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Per-charge usage receipts</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Manual grants and explicit adjustments</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Transactional outbox events</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Signed credit webhook payloads</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>In-memory and SQLite stores</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Arc Testnet USDC funding adapter</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Next.js and Express starter generation</li>\n        <li style=\"display:flex;gap:12px;padding:11px 0;border-bottom:1px solid var(--color-line-soft)\"><span style=\"color:var(--color-ink)\">+</span>Stablecoin receipt and x402 compatibility modules</li>\n      </ul>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto\">\n      <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">05 / Usage pricing</div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:44px 60px;align-items:start\">\n        <div style=\"display:flex;flex-direction:column;gap:22px\">\n          <h2 style=\"margin:0;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:22ch;text-wrap:balance\">Price the usage your provider returns</h2>\n          <p style=\"margin:0;font-size:16px;line-height:1.6;color:var(--color-ink-body)\">A meter can rate one or more integer dimensions. Each immutable price version keeps old receipts tied to the rates used at the time of the charge.</p>\n          <p style=\"margin:0;padding:16px 18px;border-left:1px solid rgba(242,242,240,0.28);font-size:14.5px;line-height:1.6;color:var(--color-ink-subtle)\">The alpha supports linear multi-dimensional rates. Tiering, packages, subscriptions, monthly minimums, and allowances are outside the current scope.</p>\n        </div>\n        <dl style=\"margin:0;display:flex;flex-direction:column\">\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);gap:20px;padding:16px 0;border-top:1px solid var(--color-line)\">\n            <dt style=\"font-size:16px;font-weight:500\">LLM chat</dt>\n            <dd style=\"margin:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink-muted)\">input tokens · output tokens</dd>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);gap:20px;padding:16px 0;border-top:1px solid var(--color-line)\">\n            <dt style=\"font-size:16px;font-weight:500\">Image generation</dt>\n            <dd style=\"margin:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink-muted)\">images · compute seconds</dd>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);gap:20px;padding:16px 0;border-top:1px solid var(--color-line)\">\n            <dt style=\"font-size:16px;font-weight:500\">AI agents</dt>\n            <dd style=\"margin:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink-muted)\">tool calls · steps · runtime</dd>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);gap:20px;padding:16px 0;border-top:1px solid var(--color-line)\">\n            <dt style=\"font-size:16px;font-weight:500\">Speech and video</dt>\n            <dd style=\"margin:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink-muted)\">seconds · minutes processed</dd>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);gap:20px;padding:16px 0;border-top:1px solid var(--color-line)\">\n            <dt style=\"font-size:16px;font-weight:500\">Batch jobs</dt>\n            <dd style=\"margin:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink-muted)\">items · pages · completed jobs</dd>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);gap:20px;padding:16px 0;border-top:1px solid var(--color-line);border-bottom:1px solid var(--color-line)\">\n            <dt style=\"font-size:16px;font-weight:500\">Developer APIs</dt>\n            <dd style=\"margin:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink-muted)\">requests · domain-specific units</dd>\n          </div>\n        </dl>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto\">\n      <div style=\"display:flex;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;gap:28px;margin-bottom:44px\">\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">06 / TypeScript SDK</div>\n          <h2 style=\"margin:0 0 18px;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:26ch;text-wrap:balance\">Wrap each provider call in a metered lifecycle</h2>\n          <p style=\"margin:0;max-width:62ch;font-size:16px;line-height:1.6;color:var(--color-ink-body)\"><code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:14px;color:var(--color-ink)\">runMetered</code> reserves estimated usage, runs your provider callback, commits the final charge, and returns the released amount with a receipt.</p>\n        </div>\n        <button data-claude-ref=\"setCopyBtn\" aria-live=\"polite\" type=\"button\" style=\"flex:none;padding:13px 18px;background:transparent;border:1px solid var(--color-line-strong);color:rgba(242,242,240,0.8);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11.5px;letter-spacing:0.12em;text-transform:uppercase;cursor:pointer;transition:border-color .2s, color .2s\" data-hover-style=\"border-color:var(--color-ink-subtle);color:var(--color-white)\">Copy code</button>\n      </div>\n      <div style=\"border:1px solid var(--color-line);background:var(--color-code-surface)\">\n        <div style=\"display:flex;align-items:center;gap:14px;padding:12px 18px;border-bottom:1px solid var(--color-line);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11.5px;letter-spacing:0.1em;color:var(--color-ink-muted)\">\n          <span style=\"width:5px;height:5px;background:rgba(242,242,240,0.3)\"></span>metered-request.ts\n        </div>\n        <pre data-claude-ref=\"setCode\" style=\"margin:0;padding:26px 24px;overflow-x:auto;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;line-height:1.75;color:rgba(242,242,240,0.82)\"><span style=\"color:var(--color-ink-subtle)\">import</span> { CreditLedger } <span style=\"color:var(--color-ink-subtle)\">from</span> <span style=\"color:var(--color-ink)\">'@resvary/sdk/credits'</span>;\n<span style=\"color:var(--color-ink-subtle)\">import</span> { createSqliteCreditStore } <span style=\"color:var(--color-ink-subtle)\">from</span> <span style=\"color:var(--color-ink)\">'@resvary/sqlite'</span>;\n\n<span style=\"color:var(--color-ink-subtle)\">const</span> credits = <span style=\"color:var(--color-ink-subtle)\">new</span> CreditLedger({\n  projectId: <span style=\"color:var(--color-ink)\">'my_ai_product'</span>,\n  store: createSqliteCreditStore({\n    path: <span style=\"color:var(--color-ink)\">'.resvary/resvary.sqlite'</span>,\n  }),\n});\n\n<span style=\"color:var(--color-ink-subtle)\">const</span> result = <span style=\"color:var(--color-ink-subtle)\">await</span> credits.runMetered(\n  {\n    customerId: <span style=\"color:var(--color-ink)\">'customer_123'</span>,\n    priceId: <span style=\"color:var(--color-ink)\">'price_llm_v1'</span>,\n    estimatedUsage: {\n      input_tokens: <span style=\"color:var(--color-ink)\">'2000'</span>,\n      output_tokens: <span style=\"color:var(--color-ink)\">'1000'</span>,\n    },\n    idempotencyKey: <span style=\"color:var(--color-ink)\">'request_abc'</span>,\n  },\n  <span style=\"color:var(--color-ink-subtle)\">async</span> () =&gt; {\n    <span style=\"color:var(--color-ink-subtle)\">const</span> completion = <span style=\"color:var(--color-ink-subtle)\">await</span> callModel();\n\n    <span style=\"color:var(--color-ink-subtle)\">return</span> {\n      value: completion,\n      usageEventId: completion.id,\n      actualUsage: {\n        input_tokens: String(completion.usage.inputTokens),\n        output_tokens: String(completion.usage.outputTokens),\n      },\n    };\n  },\n);\n\nconsole.log(result.receipt.amount);\nconsole.log(result.receipt.releasedAmount);</pre>\n      </div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:30px;margin-top:30px\">\n        <p style=\"margin:0;font-size:15px;line-height:1.6;color:var(--color-ink-body)\">If the provider throws, <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">runMetered</code> releases the full reservation. If provider execution succeeds but the commit fails, the reservation stays open so your application can retry the same commit without giving away completed usage.</p>\n        <p style=\"margin:0;font-size:15px;line-height:1.6;color:var(--color-ink-subtle)\">The packages currently live in the Resvary monorepo. Use the <a href=\"https://github.com/horn111/resvary/blob/main/docs/getting-started.md\" style=\"color:var(--color-ink);border-bottom:1px solid rgba(242,242,240,0.35)\">setup guide</a> until public package releases are available.</p>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"demo\" data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:min(8vw,110px);align-items:start\">\n      <div style=\"display:flex;flex-direction:column;gap:22px\">\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted)\">07 / Demo</div>\n        <h2 style=\"margin:0;font-size:clamp(30px,3.6vw,54px);line-height:1.02;letter-spacing:-0.032em;font-weight:500;max-width:20ch;text-wrap:balance\">Run the credit lifecycle in one demo</h2>\n        <p style=\"margin:0;font-size:16.5px;line-height:1.6;color:var(--color-ink-body)\">The deterministic demo needs no AI key. Grant credits, run a request, replay it without a second charge, or trigger a provider failure and inspect the stored result.</p>\n        <a href=\"#interactive-demo\" style=\"align-self:flex-start;display:inline-flex;align-items:center;gap:10px;padding:14px 22px;background:var(--color-ink);color:var(--color-canvas);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;transition:opacity .2s\" data-hover-style=\"opacity:0.82;color:var(--color-canvas)\">Run the interactive demo <span style=\"opacity:0.5\">→</span></a>\n      </div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:36px\">\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:12px;border-bottom:1px solid var(--color-line)\">Demo actions</div>\n          <ul style=\"list-style:none;margin:0;padding:0;font-size:14.5px;line-height:1.5;color:var(--color-ink-body)\">\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Grant $5 in development credits</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Run a simulated AI operation</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Replay the same request</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Simulate provider failure</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Simulate an Arc Testnet funding confirmation</li>\n          </ul>\n        </div>\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:12px;border-bottom:1px solid var(--color-line)\">Data exposed</div>\n          <ul style=\"list-style:none;margin:0;padding:0;font-size:14.5px;line-height:1.5;color:var(--color-ink-body)\">\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Posted, reserved, and available balances</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Reservation status</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Actual charge and released amount</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Price line items</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Immutable ledger history</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Usage receipts</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Transactional outbox events</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Signed event headers</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n      <div id=\"interactive-demo\" data-claude-demo-root=\"true\"></div>\n  </section>\n\n  <section id=\"use-cases\" data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto\">\n      <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">08 / Use cases</div>\n      <h2 style=\"margin:0 0 56px;font-size:clamp(30px,3.6vw,54px);line-height:1.02;letter-spacing:-0.032em;font-weight:500;max-width:22ch;text-wrap:balance\">Add prepaid credits to variable-cost AI workloads</h2>\n      <div style=\"display:flex;flex-direction:column\">\n        <div style=\"display:grid;grid-template-columns:minmax(0,0.55fr) minmax(0,1.45fr);gap:32px;padding:26px 0;border-top:1px solid var(--color-line);transition:transform .3s\" data-hover-style=\"transform:translateX(12px)\">\n          <h3 style=\"margin:0;font-size:21px;font-weight:500;letter-spacing:-0.02em\">AI SaaS</h3>\n          <p style=\"margin:0;font-size:16px;line-height:1.55;color:var(--color-ink-body);max-width:70ch\">Sell prepaid product credits while keeping subscriptions, checkout, and invoices in your existing billing stack.</p>\n        </div>\n        <div style=\"display:grid;grid-template-columns:minmax(0,0.55fr) minmax(0,1.45fr);gap:32px;padding:26px 0;border-top:1px solid var(--color-line);transition:transform .3s\" data-hover-style=\"transform:translateX(12px)\">\n          <h3 style=\"margin:0;font-size:21px;font-weight:500;letter-spacing:-0.02em\">AI APIs</h3>\n          <p style=\"margin:0;font-size:16px;line-height:1.55;color:var(--color-ink-body);max-width:70ch\">Authorize requests before execution and reconcile each customer charge to provider usage.</p>\n        </div>\n        <div style=\"display:grid;grid-template-columns:minmax(0,0.55fr) minmax(0,1.45fr);gap:32px;padding:26px 0;border-top:1px solid var(--color-line);transition:transform .3s\" data-hover-style=\"transform:translateX(12px)\">\n          <h3 style=\"margin:0;font-size:21px;font-weight:500;letter-spacing:-0.02em\">Agent platforms</h3>\n          <p style=\"margin:0;font-size:16px;line-height:1.55;color:var(--color-ink-body);max-width:70ch\">Reserve a budget for an agent run, then charge for its final steps, tools, tokens, or runtime.</p>\n        </div>\n        <div style=\"display:grid;grid-template-columns:minmax(0,0.55fr) minmax(0,1.45fr);gap:32px;padding:26px 0;border-top:1px solid var(--color-line);transition:transform .3s\" data-hover-style=\"transform:translateX(12px)\">\n          <h3 style=\"margin:0;font-size:21px;font-weight:500;letter-spacing:-0.02em\">Generation products</h3>\n          <p style=\"margin:0;font-size:16px;line-height:1.55;color:var(--color-ink-body);max-width:70ch\">Rate images, audio, video, or batch jobs with units that match your provider costs.</p>\n        </div>\n        <div style=\"display:grid;grid-template-columns:minmax(0,0.55fr) minmax(0,1.45fr);gap:32px;padding:26px 0;border-top:1px solid var(--color-line);border-bottom:1px solid var(--color-line);transition:transform .3s\" data-hover-style=\"transform:translateX(12px)\">\n          <h3 style=\"margin:0;font-size:21px;font-weight:500;letter-spacing:-0.02em\">Paid developer tools</h3>\n          <p style=\"margin:0;font-size:16px;line-height:1.55;color:var(--color-ink-body);max-width:70ch\">Give teams auditable credit balances and retry-safe usage charges without building a ledger from scratch.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:min(8vw,110px);align-items:start\">\n      <div style=\"display:flex;flex-direction:column;gap:22px\">\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted)\">09 / Transactions</div>\n        <h2 style=\"margin:0;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:22ch;text-wrap:balance\">Balance changes stay inside one transaction</h2>\n        <p style=\"margin:0;font-size:16px;line-height:1.6;color:var(--color-ink-body)\">Each balance-changing command validates idempotency, checks the account and lifecycle state, writes ledger entries, updates the account snapshot, stores the domain record and outbox event, and saves the command result before commit.</p>\n        <p style=\"margin:0;font-size:16px;line-height:1.6;color:var(--color-ink-body)\">The SQLite store uses <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">BEGIN IMMEDIATE</code> to serialize competing writers. It stores balances, reservations, receipts, idempotency results, and outbox events across restarts.</p>\n        <p style=\"margin:0;padding:16px 18px;border-left:1px solid rgba(242,242,240,0.28);font-size:14.5px;line-height:1.6;color:var(--color-ink-subtle)\">SQLite supports local, single-node, and design-partner deployments in the current alpha. Multi-process production deployments should use a custom <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:rgba(242,242,240,0.75)\">CreditStore</code> with equivalent transaction isolation or wait for the planned Postgres adapter.</p>\n      </div>\n      <div style=\"display:flex;flex-direction:column;gap:40px\">\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:14px;border-bottom:1px solid var(--color-line)\">Balance definitions</div>\n          <div style=\"display:flex;flex-direction:column\">\n            <div style=\"display:grid;grid-template-columns:120px minmax(0,1fr);gap:20px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n              <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Posted</span>\n              <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">Granted credits minus committed charges</span>\n            </div>\n            <div style=\"display:grid;grid-template-columns:120px minmax(0,1fr);gap:20px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n              <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Reserved</span>\n              <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">Credits held by open reservations</span>\n            </div>\n            <div style=\"display:grid;grid-template-columns:120px minmax(0,1fr);gap:20px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n              <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Available</span>\n              <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">Posted minus reserved</span>\n            </div>\n          </div>\n        </div>\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:14px;border-bottom:1px solid var(--color-line)\">Circle-native funding</div>\n          <p style=\"margin:16px 0 0;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">Direct Arc USDC and Circle Gateway Nanopayments are first-class funding paths. Each external payment becomes one funding transaction and one credit grant, keyed by <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">rail + network + external payment ID</code>. Usage accounting remains payment-rail agnostic.</p>\n          <div style=\"margin-top:18px;padding:12px 16px;border:1px dashed var(--color-line-strong);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11.5px;line-height:1.7;letter-spacing:0.08em;color:var(--color-ink-muted)\">Arc invoice → memo proof → payment receipt → funding confirmation → credit grant</div>\n          <div style=\"display:flex;flex-direction:column;gap:8px;margin-top:20px;font-size:14.5px;line-height:1.55;color:var(--color-ink-muted)\">\n            <span>A payment receipt proves which external transfer funded an account.</span>\n            <span>A usage receipt explains why product credits were charged.</span>\n          </div>\n          <p style=\"margin:18px 0 0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11.5px;line-height:1.7;letter-spacing:0.06em;color:var(--color-ink-muted)\">The current Arc integration is Testnet-first development infrastructure.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto\">\n      <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">10 / Credit model</div>\n      <h2 style=\"margin:0 0 48px;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:30ch;text-wrap:balance\">A credit balance needs a transaction lifecycle</h2>\n      <table data-credit-model-table=\"true\" style=\"width:100%;border-collapse:collapse;text-align:left\">\n        <thead>\n          <tr style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted)\">\n            <th scope=\"col\" style=\"padding:0 16px 14px 0;font-weight:400;border-bottom:1px solid var(--color-line-strong)\">Capability</th>\n            <th scope=\"col\" style=\"padding:0 16px 14px;font-weight:400;border-bottom:1px solid var(--color-line-strong);width:22%\">Balance column</th>\n            <th scope=\"col\" style=\"padding:0 0 14px 16px;font-weight:400;border-bottom:1px solid var(--color-line-strong);width:22%\">Resvary 0.4 alpha</th>\n          </tr>\n        </thead>\n        <tbody style=\"font-size:15.5px;color:var(--color-ink-body)\">\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Available balance snapshot</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Yes</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Yes</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Atomic pre-request reservation</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Custom work</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Included</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Actual-usage commit and release</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Custom work</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Included</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Retry-safe mutating commands</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Custom work</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Included</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Immutable price history</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Custom work</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Included</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Per-charge usage receipts</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Custom work</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Included</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Append-only ledger entries</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Custom work</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Included</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Transactional outbox events</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Custom work</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">Included</td></tr>\n          <tr><td style=\"padding:15px 16px 15px 0;border-bottom:1px solid var(--color-line-soft)\">Funding rail independence</td><td style=\"padding:15px 16px;border-bottom:1px solid var(--color-line-soft);color:var(--color-ink-subtle);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px\">Depends on implementation</td><td style=\"padding:15px 0 15px 16px;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">In the domain model</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto\">\n      <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">11 / Alpha boundary</div>\n      <h2 style=\"margin:0 0 20px;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:26ch;text-wrap:balance\">Know the alpha boundary before you integrate</h2>\n      <p style=\"margin:0 0 56px;max-width:74ch;font-size:16px;line-height:1.6;color:var(--color-ink-body)\">Resvary 0.4 includes the embedded credit domain, SQLite persistence, direct Arc Testnet funding, and Gateway Nanopayment funding. Hosted billing, Postgres, mainnet settlement, and multi-node deployment remain planned work.</p>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:44px\">\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:14px;border-bottom:1px solid var(--color-line)\">Supported boundary</div>\n          <ul style=\"list-style:none;margin:0;padding:0;font-size:15px;line-height:1.5;color:var(--color-ink-body)\">\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Credits belong to one merchant project</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Credits cannot move between users</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Users cannot redeem or cash out credits</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Resvary does not custody customer funds</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Usage receipts are operational records, not tax invoices</li>\n          </ul>\n        </div>\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:14px;border-bottom:1px solid var(--color-line)\">Not in the current alpha</div>\n          <ul style=\"list-style:none;margin:0;padding:0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12.5px;line-height:1.5;color:var(--color-ink-subtle)\">\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Hosted dashboard or managed API</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Postgres adapter</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Multi-node deployment support</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Subscription management · checkout UI</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Tax calculation or tax invoices</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Transferable balances · cash redemption</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Marketplace wallets</li>\n            <li style=\"padding:11px 0;border-bottom:1px solid var(--color-line-soft)\">Enterprise SLA or compliance certification</li>\n          </ul>\n        </div>\n        <div>\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:14px;border-bottom:1px solid var(--color-line)\">Planned direction</div>\n          <ul style=\"list-style:none;margin:0;padding:0;font-size:15px;line-height:1.5;color:var(--color-ink-body)\">\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Postgres persistence</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Self-hosted HTTP service</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Hosted operations and delivery tooling</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Access control and operator workflows</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Analytics and reconciliation views</li>\n          </ul>\n          <p style=\"margin:16px 0 0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;line-height:1.7;letter-spacing:0.06em;color:var(--color-ink-muted)\">Roadmap items, not available features.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:min(8vw,110px);align-items:start\">\n      <div style=\"display:flex;flex-direction:column;gap:22px\">\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted)\">12 / Open source</div>\n        <h2 style=\"margin:0;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:20ch;text-wrap:balance\">Keep the credit ledger inside your application</h2>\n        <p style=\"margin:0;font-size:16px;line-height:1.6;color:var(--color-ink-body)\">Run the Apache-2.0 TypeScript code inside your application. Inspect the balance rules, run the tests, use the store interface, and keep product usage in your infrastructure.</p>\n        <div style=\"display:flex;flex-wrap:wrap;gap:12px;margin-top:6px\">\n          <a href=\"https://github.com/horn111/resvary\" style=\"display:inline-flex;align-items:center;gap:10px;padding:14px 22px;background:var(--color-ink);color:var(--color-canvas);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;transition:opacity .2s\" data-hover-style=\"opacity:0.82;color:var(--color-canvas)\">View the repository</a>\n          <a href=\"https://github.com/horn111/resvary/blob/main/docs/architecture.md\" style=\"display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:1px solid var(--color-line-strong);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-strong);transition:border-color .2s, color .2s\" data-hover-style=\"border-color:var(--color-ink-subtle);color:var(--color-white)\">Read the architecture</a>\n        </div>\n      </div>\n      <div>\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:14px;border-bottom:1px solid var(--color-line)\">Repository components</div>\n        <div style=\"display:flex;flex-direction:column\">\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">@resvary/sdk/credits</code>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Accounts, grants, reservations, usage receipts, ledger, idempotency, outbox</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">@resvary/sdk/pricing</code>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Meters, immutable price versions, integer usage rating</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">@resvary/sdk/funding/arc</code>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Arc payment receipt to credit grant adapter</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">@resvary/sqlite</code>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Persistent credit and payment receipt stores</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">@resvary/sdk/receipts</code>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Stablecoin invoices, proofs, payment receipts, signed webhooks</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">@resvary/sdk/middleware</code>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Compatible legacy x402 middleware for Express and Next.js</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13px;color:var(--color-ink)\">create-resvary</code>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Starter generator for prepaid AI credit applications</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"pricing\" data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:flex;flex-direction:column;gap:56px\">\n      <div style=\"display:grid;grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr);gap:min(8vw,110px);align-items:end\">\n        <div style=\"display:flex;flex-direction:column;gap:22px\">\n          <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted)\">13 / Access</div>\n          <h2 style=\"margin:0;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:20ch;text-wrap:balance\">Run the open-source alpha or request an integration review</h2>\n        </div>\n        <p style=\"margin:0;font-size:16px;line-height:1.6;color:var(--color-ink-body);max-width:56ch\">Run Resvary in your application today. Design-partner reviews are available for a small number of AI teams. A managed service remains a roadmap item with no launch date or price.</p>\n      </div>\n\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px\">\n        <div style=\"border:1px solid var(--color-line);padding:32px 30px 34px;display:flex;flex-direction:column;gap:22px\">\n          <div style=\"display:flex;flex-direction:column;gap:10px\">\n            <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted)\">Open-source alpha</span>\n            <span style=\"font-size:clamp(30px,3vw,42px);line-height:1;letter-spacing:-0.03em;font-weight:500\">Apache-2.0</span>\n            <span style=\"font-size:14.5px;line-height:1.5;color:var(--color-ink-muted)\">Source available now</span>\n          </div>\n          <ul style=\"margin:0;padding:0;list-style:none;font-size:15px;line-height:1.5;color:var(--color-ink-body);border-top:1px solid var(--color-line)\">\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Full credit ledger and pricing engine</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">SQLite store, embedded or as a service</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Arc funding adapter and signed webhooks</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">No usage caps, no telemetry, no vendor account</li>\n            <li style=\"padding:12px 0\">Community support through GitHub issues</li>\n          </ul>\n          <a href=\"https://github.com/horn111/resvary\" style=\"align-self:flex-start;margin-top:auto;display:inline-flex;align-items:center;gap:10px;padding:14px 22px;background:var(--color-ink);color:var(--color-canvas);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;transition:opacity .2s\" data-hover-style=\"opacity:0.82;color:var(--color-canvas)\">Open the repository</a>\n        </div>\n        <div style=\"border:1px solid var(--color-line);padding:32px 30px 34px;display:flex;flex-direction:column;gap:22px\">\n          <div style=\"display:flex;flex-direction:column;gap:10px\">\n            <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted)\">Design partner</span>\n            <span style=\"font-size:clamp(30px,3vw,42px);line-height:1;letter-spacing:-0.03em;font-weight:500\">Alpha review</span>\n            <span style=\"font-size:14.5px;line-height:1.5;color:var(--color-ink-muted)\">Limited slots during 0.4 alpha</span>\n          </div>\n          <ul style=\"margin:0;padding:0;list-style:none;font-size:15px;line-height:1.5;color:var(--color-ink-body);border-top:1px solid var(--color-line)\">\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Everything in self-hosted</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Direct channel to the maintainers</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Integration review of your metering model</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Influence over the Postgres adapter and API surface</li>\n            <li style=\"padding:12px 0\">Migration help when the schema changes</li>\n          </ul>\n          <a href=\"https://github.com/horn111/resvary/issues/new\" style=\"align-self:flex-start;margin-top:auto;display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:1px solid var(--color-line-strong);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-strong);transition:border-color .2s, color .2s\" data-hover-style=\"border-color:var(--color-ink-subtle);color:var(--color-white)\">Request an alpha review</a>\n        </div>\n        <div style=\"border:1px solid var(--color-line);padding:32px 30px 34px;display:flex;flex-direction:column;gap:22px\">\n          <div style=\"display:flex;flex-direction:column;gap:10px\">\n            <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-subtle)\">Managed service</span>\n            <span style=\"font-size:clamp(30px,3vw,42px);line-height:1;letter-spacing:-0.03em;font-weight:500;color:var(--color-ink-muted)\">Planned</span>\n            <span style=\"font-size:14.5px;line-height:1.5;color:var(--color-ink-subtle)\">Roadmap, no launch date</span>\n          </div>\n          <ul style=\"margin:0;padding:0;list-style:none;font-size:15px;line-height:1.5;color:var(--color-ink-muted);border-top:1px solid var(--color-line)\">\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Hosted ledger with managed backups</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Operator console and audit exports</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Reconciliation and analytics views</li>\n            <li style=\"padding:12px 0;border-bottom:1px solid var(--color-line-soft)\">Uptime commitments and support terms</li>\n            <li style=\"padding:12px 0\">Same SDK, no application rewrite</li>\n          </ul>\n          <span style=\"align-self:flex-start;margin-top:auto;display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:1px dashed var(--color-line);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-subtle)\">Not available yet</span>\n        </div>\n      </div>\n\n      <div>\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.14em;text-transform:uppercase;color:var(--color-ink-muted);padding-bottom:14px;border-bottom:1px solid var(--color-line)\">What you operate in the current alpha</div>\n        <div style=\"display:flex;flex-direction:column\">\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.7fr) minmax(0,1.15fr) minmax(0,1.15fr);gap:24px;padding:14px 0;border-bottom:1px solid var(--color-line-soft);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:10.5px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-muted)\">\n            <span>Concern</span><span>You run it</span><span>Managed service, when available</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.7fr) minmax(0,1.15fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink)\">Data location</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">Usage and balances never leave your infrastructure</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Ledger stored on Resvary infrastructure</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.7fr) minmax(0,1.15fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink)\">Store</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">SQLite today; a Postgres adapter is planned</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Managed Postgres with backups</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.7fr) minmax(0,1.15fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink)\">Upgrades</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">You pin versions and apply schema migrations</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Rolling upgrades with versioned API guarantees</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.7fr) minmax(0,1.15fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink)\">Availability</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">Your deployment, your monitoring and on-call</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Support terms and uptime commitments</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.7fr) minmax(0,1.15fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink)\">Payments</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">Your wallet and Circle integration, your merchant terms</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">Unchanged — Resvary never holds customer funds</span>\n          </div>\n          <div style=\"display:grid;grid-template-columns:minmax(0,0.7fr) minmax(0,1.15fr) minmax(0,1.15fr);gap:24px;padding:16px 0;border-bottom:1px solid var(--color-line-soft)\">\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink)\">Cost</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-body)\">Your compute and storage only</span>\n            <span style=\"font-size:15px;line-height:1.5;color:var(--color-ink-muted)\">To be announced</span>\n          </div>\n        </div>\n        <p style=\"margin:18px 0 0;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;line-height:1.7;letter-spacing:0.06em;color:var(--color-ink-muted)\">Managed cloud is a roadmap item. No hosted plan, contract, or price exists today.</p>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:100px 34px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:grid;grid-template-columns:minmax(0,0.6fr) minmax(0,1.4fr);gap:min(8vw,100px);align-items:start\">\n      <div>\n        <div style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.16em;text-transform:uppercase;color:var(--color-ink-muted);margin-bottom:26px\">14 / FAQ</div>\n        <h2 style=\"margin:0;font-size:clamp(28px,3.2vw,46px);line-height:1.05;letter-spacing:-0.03em;font-weight:500;max-width:14ch;text-wrap:balance\">Questions engineers ask first</h2>\n      </div>\n      <div style=\"display:flex;flex-direction:column;border-top:1px solid var(--color-line)\">\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Is Resvary a payment processor?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">No. Resvary manages closed-loop product credits and usage authorization. Keep checkout, subscriptions, tax, and fiat payment processing in the systems you already use.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Does Resvary replace Stripe Billing, Lago, or Orb?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">Resvary handles the real-time credit boundary around an AI operation. A broader billing platform can continue to handle checkout, subscriptions, invoicing, or finance workflows.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Why reserve credits before the AI request?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">The final provider cost arrives after execution. A reservation prevents concurrent requests from spending the same available balance while keeping the final charge tied to actual usage.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">What happens when the provider fails?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\"><code style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:13.5px;color:var(--color-ink)\">runMetered</code> releases the full reservation when the provider callback throws. The account keeps its posted credits.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">What happens if commit fails after the AI request succeeds?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">The reservation stays open. Retry the commit with the same idempotency key to record the completed usage without charging twice.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Can an actual charge exceed its reservation?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">No. Your application must create another reservation before continuing work that needs a higher limit.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Can I use my existing AI provider?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">Yes. The core ledger does not depend on a model vendor. Your application passes estimated and actual usage into the SDK.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Do I need crypto or Arc to use Resvary?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">No. Manual grants work without a blockchain. Direct Arc USDC and Gateway Nanopayments are Testnet funding options; neither changes the usage ledger.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Is SQLite production-ready?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">The current SQLite adapter targets local, single-node, and design-partner deployments. Multi-process production deployments need a store with equivalent transaction isolation. A Postgres adapter is planned.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Are credits transferable or redeemable?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">No. Resvary models non-transferable, non-redeemable product credits that customers use inside one merchant project.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Is a usage receipt a tax invoice?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">No. A usage receipt explains an operational credit charge. Each merchant remains responsible for its customer terms, refund policy, privacy notice, invoices, and tax treatment.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">Is Resvary free to use?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">The current code is available under the Apache-2.0 license. No hosted paid plan exists yet.</p>\n        </details>\n        <details style=\"border-bottom:1px solid var(--color-line)\">\n          <summary style=\"display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;font-size:17px;font-weight:500;letter-spacing:-0.015em\">How do I try the alpha?<span class=\"faq-plus\" aria-hidden=\"true\" style=\"flex:none;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:16px;color:var(--color-ink-subtle);transition:transform .25s\">+</span></summary>\n          <p style=\"margin:0;padding:0 0 22px;max-width:70ch;font-size:15.5px;line-height:1.6;color:var(--color-ink-body)\">Run the deterministic demo without an AI key, or open the repository and follow the getting-started guide.</p>\n        </details>\n      </div>\n    </div>\n  </section>\n\n  <section data-reveal=\"1\" style=\"border-top:1px solid var(--color-line);padding:120px 34px 130px;text-align:center\">\n    <div style=\"max-width:900px;margin:0 auto;display:flex;flex-direction:column;align-items:center;gap:26px\">\n      <h2 style=\"margin:0;font-size:clamp(32px,4.4vw,66px);line-height:1.02;letter-spacing:-0.036em;font-weight:500;max-width:24ch;text-wrap:balance\">Add a retry-safe credit ledger to your next AI request</h2>\n      <p style=\"margin:0;max-width:62ch;font-size:17px;line-height:1.6;color:var(--color-ink-body)\">Run the lifecycle in the demo, then evaluate the open-source SDK inside your application.</p>\n      <div style=\"display:flex;flex-wrap:wrap;justify-content:center;gap:12px;margin-top:8px\">\n        <a href=\"#interactive-demo\" style=\"display:inline-flex;align-items:center;gap:10px;padding:15px 24px;background:var(--color-ink);color:var(--color-canvas);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;transition:opacity .2s\" data-hover-style=\"opacity:0.82;color:var(--color-canvas)\">Run the live demo <span style=\"opacity:0.5\">→</span></a>\n        <a href=\"https://github.com/horn111/resvary\" style=\"display:inline-flex;align-items:center;gap:10px;padding:15px 24px;border:1px solid var(--color-line-strong);font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-strong);transition:border-color .2s, color .2s\" data-hover-style=\"border-color:var(--color-ink-subtle);color:var(--color-white)\">View the repository</a>\n      </div>\n    </div>\n  </section>\n\n  </main><footer style=\"border-top:1px solid var(--color-line);padding:56px 34px 44px\">\n    <div style=\"max-width:1280px;margin:0 auto;display:flex;flex-wrap:wrap;align-items:flex-start;justify-content:space-between;gap:40px\">\n      <div style=\"display:flex;flex-direction:column;gap:14px;max-width:44ch\">\n        <span style=\"font-size:18px;font-weight:500;letter-spacing:-0.02em\">Resvary.</span>\n        <p style=\"margin:0;font-size:15px;line-height:1.55;color:var(--color-ink-muted)\">Open-source prepaid credits and usage billing for AI products.</p>\n        <span style=\"font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:var(--color-ink-muted)\">Resvary 0.4 alpha · Apache-2.0</span>\n      </div>\n      <nav aria-label=\"Footer\" style=\"display:grid;grid-template-columns:repeat(2,minmax(140px,auto));gap:10px 48px;font-family:var(--font-mono),'JetBrains Mono',monospace;font-size:12px;letter-spacing:0.1em;text-transform:uppercase;color:var(--color-ink-body)\">\n        <a href=\"https://github.com/horn111/resvary\" style=\"transition:color .2s\">GitHub</a>\n        <a href=\"https://github.com/horn111/resvary#readme\" style=\"transition:color .2s\">Documentation</a>\n        <a href=\"#interactive-demo\" style=\"transition:color .2s\">Live demo</a>\n        <a href=\"https://github.com/horn111/resvary/blob/main/LICENSE\" style=\"transition:color .2s\">License</a>\n        <a href=\"https://github.com/horn111/resvary/blob/main/SECURITY.md\" style=\"transition:color .2s\">Security</a>\n        <a href=\"https://github.com/horn111/resvary/issues\" style=\"transition:color .2s\">Issues</a>\n      </nav>\n    </div>\n    <div style=\"max-width:1280px;margin:52px auto 0;width:100%;aspect-ratio:4.05 / 1\">\n      <canvas data-claude-ref=\"setFooterCanvas\" style=\"display:block;width:100%;height:100%\"></canvas>\n    </div>\n\n    <p style=\"max-width:1280px;margin:36px auto 0;padding-top:24px;border-top:1px solid var(--color-line-soft);font-size:13.5px;line-height:1.6;color:var(--color-ink-muted)\">Resvary provides billing software for closed-loop product credits. It does not provide custody, tax invoices, transferable balances, or cash redemption.</p>\n  </footer>\n</div>";
